12	declare_lint_rule! {
13	    /// Disallow the use of `eval()`-like methods.
14	    ///
15	    /// The `eval()` function evaluates the passed string as a _JavaScript_ code.
16	    /// Calling `setTimeout`, `setInterval`, or `setImmediate` with a string argument
17	    /// is an implied `eval()` because the string is evaluated as code.
18	    ///
19	    /// Using implied `eval()` is considered a bad practice because:
20	    /// 1. It exposes your code to security risks and performance issues
21	    /// 2. The code is evaluated in the global scope rather than the local scope
22	    /// 3. It prevents the JavaScript engine from optimizing the code
23	    ///
24	    /// ## Examples
25	    ///
26	    /// ### Invalid
27	    ///
28	    /// ```js,expect_diagnostic
29	    /// setTimeout("alert('Hello world!');", 100);
30	    /// ```
31	    ///
32	    /// ```js,expect_diagnostic
33	    /// setInterval("alert('Hello world!');", 100);
34	    /// ```
35	    ///
36	    /// ```js,expect_diagnostic
37	    /// setImmediate("alert('Hello world!');");
38	    /// ```
39	    ///
40	    /// ```js,expect_diagnostic
41	    /// window.setTimeout("count = 5", 10);
42	    /// ```
43	    ///
44	    /// ```js,expect_diagnostic
45	    /// window.setInterval("foo = bar", 10);
46	    /// ```
47	    ///
48	    /// ### Valid
49	    ///
50	    /// ```js
51	    /// setTimeout(function() {
52	    ///     alert('Hello world!');
53	    /// }, 100);
54	    /// ```
55	    ///
56	    /// ```js
57	    /// setInterval(() => {
58	    ///     alert('Hello world!');
59	    /// }, 100);
60	    /// ```
61	    ///
62	    /// ```js
63	    /// // setTimeout is shadowed by a local variable
64	    /// function foo(setTimeout) {
65	    ///     setTimeout("alert('Hello world!');", 100);
66	    /// }
67	    /// ```
68	    ///
69	    /// ## Resources
70	    ///
71	    /// - [MDN setTimeout() documentation](https://developer.mozilla.org/en-US/docs/Web/API/setTimeout#the_string_problem)
72	    /// - [MDN eval() documentation](https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/eval#never_use_direct_eval!)
73	    ///
74	    pub NoImpliedEval {
75	        version: "next",
76	        name: "noImpliedEval",
77	        language: "js",
78	        sources: &[
79	            RuleSource::Eslint("no-implied-eval").same(),
80	            RuleSource::EslintTypeScript("no-implied-eval").same(),
81	        ],
82	        recommended: false,
83	        severity: Severity::Error,
84	        issue_number: Some("8735"),
85	    }
86	}
87	
88	const EVAL_LIKE_FUNCTIONS: &[&str] = &["setTimeout", "setInterval", "setImmediate"];
89	
90	impl Rule for NoImpliedEval {
91	    type Query = Semantic<JsCallExpression>;
92	    type State = ();
93	    type Signals = Option<Self::State>;
94	    type Options = NoImpliedEvalOptions;
95	
96	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
97	        let call_expr = ctx.query();
98	        let model = ctx.model();
99	
100	        let callee = call_expr.callee().ok()?;
101	
102	        if !is_eval_like_function(&callee, model)? {
103	            return None;
104	        }
105	
106	        let args = call_expr.arguments().ok()?;
107	        let first_arg = args.args().first()?.ok()?;
108	
109	        if is_string_argument(first_arg.as_any_js_expression()?) {
110	            return Some(());
111	        }
112	
113	        None
114	    }
115	
116	    fn diagnostic(ctx: &RuleContext<Self>, _: &Self::State) -> Option<RuleDiagnostic> {
117	        let call_expr = ctx.query();
118	
119	        Some(
120	            RuleDiagnostic::new(
121	                rule_category!(),
122	                call_expr.range(),
123	                markup! {
124	                    "Implied "<Emphasis>"eval()"</Emphasis>" is not allowed."
125	                },
126	            )
127	            .note(markup! {
128	                "Passing strings to functions like "<Emphasis>"setTimeout"</Emphasis>", "
129	                <Emphasis>"setInterval"</Emphasis>", or "<Emphasis>"setImmediate"</Emphasis>
130	                " is a form of implied "<Emphasis>"eval()"</Emphasis>" and can lead to security and performance issues."
131	            })
132	            .note(markup! {
133	                "Use a function instead of a string."
134	            }),
135	        )
136	    }
137	}
138	
139	/// Checks if the callee is one of the eval-like functions
140	/// Handles patterns like:
141	/// - setTimeout (direct identifier)
142	/// - window.setTimeout (static member)
143	/// - `window["setTimeout"]` (computed member)
144	/// - globalThis.setTimeout (static member)
145	///
146	/// Uses the `global_identifier` utility which handles window/globalThis chains automatically
147	fn is_eval_like_function(
148	    callee: &AnyJsExpression,
149	    model: &biome_js_semantic::SemanticModel,
150	) -> Option<bool> {
151	    let unwrapped = callee.clone().omit_parentheses();
152	    let (reference, name) = global_identifier(&unwrapped)?;
153	
154	    Some(model.binding(&reference).is_none() && EVAL_LIKE_FUNCTIONS.contains(&name.text()))
155	}
156	
157	/// Checks if the argument is a string (literal, template, or concatenation)
158	fn is_string_argument(arg: &AnyJsExpression) -> bool {
159	    let unwrapped = arg.clone().omit_parentheses();
160	
161	    match unwrapped {
162	        AnyJsLiteralExpression(lit) => lit.as_js_string_literal_expression().is_some(),
163	
164	        JsTemplateExpression(template) => {
165	            // Only flag templates with no substitutions
166	            template
167	                .elements()
168	                .iter()
169	                .all(|element| element.as_js_template_chunk_element().is_some())
170	        }
171	
172	        JsBinaryExpression(bin) => {
173	            if let Ok(operator) = bin.operator()
174	                && matches!(operator, JsBinaryOperator::Plus)
175	                && let (Ok(left), Ok(right)) = (bin.left(), bin.right())
176	            {
177	                return is_string_argument(&left) || is_string_argument(&right);
178	            }
179	            false
180	        }
181	
182	        _ => false,
183	    }
184	}
